#define UNIT_DIRECTION    0x2808eUL
#define CAN_ENTER         0x283ecUL
#define FIND_UNIT_AT      0x146dcUL
#define FIND_OBJECTIVE_AT 0x1472aUL
#define OBJECTIVE_SIDE    0x14778UL
#define GARRISON          0xe946u
#define ENTRY_SIDE        0x3da8u
#define CURSOR_X          0xbaccu
#define CURSOR_Y          0xbacdu
#define MOVE_CLASS        0xbaceu

static uint16_t word_at(const uint8_t* ds, uint16_t at) {
  return (uint16_t)(ds[at] | (uint16_t)ds[(uint16_t)(at + 1)] << 8);
}
static uint16_t call1(uint8_t* ds, BattleEvent event, uint32_t service,
                      uint16_t a0) {
  return event(ds, service, &a0, 1);
}
static uint16_t call2(uint8_t* ds, BattleEvent event, uint32_t service,
                      uint16_t a0, uint16_t a1) {
  uint16_t args[2];
  args[0] = a0;
  args[1] = a1;
  return event(ds, service, args, 2);
}
static uint8_t* map_cell(uint8_t* ds, uint8_t x, uint8_t y) {
  return &ds[(uint16_t)(0x20b6u + y * 40u + x)];
}

uint16_t opeu_battle_exit_ok(uint8_t* ds, BattleEvent event, uint8_t x,
                             uint8_t y, uint16_t element) {
  uint8_t  cx, cy, side, direction, terrain, category, mask, owner;
  uint16_t unit, objective;
  if (opeu_battle_cell_occupied(ds, event, x, y))
    return 0;
  side = (uint8_t)(ds[(uint16_t)(0x3ca2u + y * 14u + x)] >> 4);
  if (side == 0 || side >= 9)
    return 0;
  if (x != 0 && y != 0 && x != 13 && y != 13)
    return 0;
  side--;
  unit      = opeu_battle_element_unit(ds, event, element);
  direction = (uint8_t)call1(ds, event, UNIT_DIRECTION, unit);
  if (direction != 9)
    return direction == side;
  cx = ds[0x2fa2];
  cy = ds[0x2fa3];
  if (!opeu_grid_step(&cx, &cy, side))
    return 0;
  if (call2(ds, event, FIND_UNIT_AT, cx, cy))
    return 0;
  objective = call2(ds, event, FIND_OBJECTIVE_AT, cx, cy);
  if (objective) {
    owner = (uint8_t)call1(ds, event, OBJECTIVE_SIDE, objective);
    if (owner != opeu_battle_unit_side(ds, event, word_at(ds, 0x2fc0)))
      return 0;
  }
  for (element = word_at(ds, unit); element; element = word_at(ds, element)) {
    terrain  = (uint8_t)(*map_cell(ds, cx, cy) & 0x0f);
    category = ds[(uint16_t)(0x3332u + ds[(uint16_t)(element + 2)] * 13u + 4u)];
    if (ds[(uint16_t)(0x76u + terrain * 5u +
                      ds[(uint16_t)(MOVE_CLASS + category)])] == 0xff)
      return 0;
  }
  if (*map_cell(ds, cx, cy) & 0xc0) {
    mask = (uint8_t)(opeu_battle_unit_side(ds, event, unit) ? 0x80 : 0x40);
    if (*map_cell(ds, cx, cy) & mask)
      return 0;
  }
  if (unit != GARRISON && ds[ENTRY_SIDE] != side && ds[ENTRY_SIDE] != 0xff)
    return 0;
  return 1;
}

uint16_t opeu_battle_cursor_exit_ok(uint8_t* ds, BattleEvent event,
                                    uint16_t element) {
  uint16_t args[3];
  args[0] = ds[CURSOR_X];
  args[1] = ds[CURSOR_Y];
  args[2] = element;
  if (event(ds, CAN_ENTER, args, 3) &&
      opeu_battle_exit_ok(ds, event, ds[CURSOR_X], ds[CURSOR_Y], element))
    return 1;
  return 0;
}

